"""Build the evidence report from saved scores; no experiment/model mutation."""
from pathlib import Path
import json, shutil, hashlib
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, Image, PageBreak
from reportlab.lib import colors
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.enums import TA_CENTER
from reportlab.lib.pagesizes import A4

ROOT=Path(__file__).resolve().parents[2]
REPORT=ROOT/'reports/coupled-contact-v13'
OUT=ROOT/'output/pdf/coupled-contact-v13-report.pdf'
STYLE=getSampleStyleSheet()
STYLE.add(ParagraphStyle(name='Lead',fontName='Helvetica',fontSize=12,leading=17,spaceAfter=12,textColor=colors.HexColor('#263e51')))
STYLE['BodyText'].fontSize=10;STYLE['BodyText'].leading=14;STYLE['BodyText'].spaceAfter=8
STYLE['Heading1'].fontSize=22;STYLE['Heading1'].leading=26;STYLE['Heading1'].textColor=colors.HexColor('#173c50')
STYLE['Heading2'].fontSize=13;STYLE['Heading2'].leading=17;STYLE['Heading2'].spaceBefore=12
STYLE.add(ParagraphStyle(name='SmallNote',fontSize=8,leading=11,spaceAfter=6,textColor=colors.HexColor('#4b5560')))

def p(text,kind='BodyText'):return Paragraph(text,STYLE[kind])
def table(rows,widths):
    t=Table([[p(str(x),'SmallNote') for x in row] for row in rows],colWidths=widths,repeatRows=1,hAlign='LEFT')
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e4edf0')),('VALIGN',(0,0),(-1,-1),'TOP'),('BOTTOMPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),6),('LINEBELOW',(0,0),(-1,0),.6,colors.HexColor('#76939f')),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#f5f7f8')])]))
    return t
def footer(canvas,doc):
    canvas.saveState();canvas.setStrokeColor(colors.HexColor('#b8c8ce'));canvas.line(42,37,553,37);canvas.setFont('Helvetica',8)
    canvas.drawString(42,25,'Coupled-contact v13 | Simulation study | 30 October 2026');canvas.drawRightString(553,25,str(doc.page));canvas.restoreState()

def main():
    summary=json.loads((REPORT/'summary.json').read_text());reserved=summary['splits']['reserved'];methods=reserved['methods']
    nominal=json.loads((REPORT/'nominal-baseline-results.json').read_text())['splits']['reserved']
    story=[p('Position-based inference with coupled deformable contact','Heading1'),p('A completed controlled study and the numerical audit that motivates its repair','Lead'),p('The model estimates stiffness and friction from observed positions during one squeeze, shear and release, then predicts sliding, edge dropping, curved-obstacle pushing and collision with a moving sphere. This adds force exchange between deformable and rigid bodies while preserving the earlier public-dataset results.'),p('Completed reserved comparison','Heading2')]
    rows=[['Method','Complete','World RMSE (mm)','Shape RMSE (mm)']]
    labels={'fem':'Inferred nonlinear FEM','rigid':'Rigid + same contact','oracle':'True-parameter coarse FEM','native':'Adapted PhysTwin spring core','position_ridge':'Position ridge'}
    for key in ['fem','rigid','oracle','native','position_ridge']:
        s=methods[key];rows.append([labels[key],f"{s['complete']}/32",f"{s['coordinate_mean_mm']:.2f}",f"{s['shape_mean_mm']:.2f}"])
    story.extend([table(rows,[225,60,105,105]),Spacer(1,10),p(f"Fixed nominal FEM: {nominal['mean_coordinate_mm']:.2f} mm, complete on all 32 cases. Inferred FEM wins 28/32 against rigid contact and 25/32 against nominal FEM; mean world error falls by 32.3% and 13.6%, respectively. On the 20 completed spring-core pairs, inferred FEM averages 15.61 mm and wins 19/20. Repeated interactions share eight objects; 32 trajectories are not 32 independent material samples."),p('Reference limitation','Heading2'),p('The original vertex-contact reference failed spatial consistency. A development mesh change from 4 to 6 cells alters edge-drop trajectories by 12.13 and 29.72 mm. The table is therefore evidence about prediction of this frozen discretized simulator, not validated physical ground truth. All cases remain included; 26/32 reserved references pass the separate timestep and penetration checks.'),p('Shape error removes each frame\'s best rigid transformation. The shape improvement is smaller than the world-position improvement. Missing spring-core trajectories are explicit failures under this study\'s positive-element-volume guard; its reported mean is conditional on completion.','SmallNote'),PageBreak()])
    story.extend([p('Algorithm and experimental inputs','Heading1'),p('1. Represent bodies and contact','Heading2'),p('The soft block is a conforming tetrahedral mesh with lumped mass. A compressible Neo-Hookean law predicts deformation. The scene contains prescribed tools, static collision geometry and, in one scenario, a dynamic rigid sphere. Penalty normal contact and dissipative, Coulomb-capped viscous friction apply equal/opposite forces and torques. There is no self-contact or continuous collision detection.'),p('For each tetrahedron: F = Ds Dm<super>-1</super>, J = det(F). The strain energy density is W = (mu/2)(tr(F<super>T</super>F) - 3) - mu log(J) + (lambda/2)log(J)<super>2</super>. Nodal elastic forces are the negative energy gradient. Objective strain-rate viscosity and gravity are added; symplectic Euler advances velocities and positions. Any integration step with J &lt;= 0.02 is rejected.'),p('2. Infer from positions, without future object targets','Heading2'),p('Observe 18 deterministic surface nodes at 100 Hz through the full 0.6-second calibration motion, with independent 0.1 mm Gaussian position noise. Search 7 Young-modulus values by 5 friction values and select the smallest observed-position mean squared error. Initial geometry, density, Poisson ratio, viscosity, gravity, scene geometry and tool trajectories are known. Stiffness and friction are unknown. This is a discrete point estimate, not a calibrated posterior.'),p('3. Transfer parameters to different interactions','Heading2'),p('Each forecast starts from its supplied initial state. Only fitted physical parameters transfer; the forecast does not continue the calibration state. The original predictor has 2 cells per axis, the reference 4. Predictor timestep is 0.1 ms; reference 0.05 ms with a separate 0.025 ms check for every episode. All four interaction families were used in numerical development. The eight reserved material/friction combinations are new combinations within the search range, not unseen material-range extrapolation.'),p('4. Compare matched explanations','Heading2'),p('Rigid contact uses the same scene and fits friction. The oracle diagnostic receives true material/friction labels. Fixed nominal FEM uses 6000 Pa and friction 0.35. The native spring baseline uses the authors\' unchanged PhysTwin spring-force kernel on this study\'s graph, masses, contact and integration, with its own effective-scale search. It is not the full authors\' method or an official PhysTwin ranking. Position regression lacks collision geometry and is a weaker control.'),p('How much deformation is present?','Heading2'),table([['Scenario','Median nonrigid RMS','Nonrigid / world RMS'],['Calibration squeeze','1.87 mm','54.8%'],['Slide','1.03 mm','2.0%'],['Edge drop','2.67 mm','6.0%'],['Curved obstacle','1.03 mm','2.2%'],['Moving sphere','0.99 mm','2.0%']],[210,140,145]),Spacer(1,7),p('Independent population audit: all 70 references, all 125 fine-grid nodes, uniform coordinate weighting, initial frame excluded, proper rigid fit per frame. Forecast movement is predominantly rigid even though millimetre-scale deformation remains measurable.','SmallNote'),PageBreak()])
    story.extend([p('Audit, preservation and repair','Heading1'),Image(str(REPORT/'reserved-comparison.png'),width=495,height=275),p('All 32 reserved cases are shown. Below the diagonal favors inferred FEM. These comparisons retain the failed spatial-reference qualification.','SmallNote'),p('Verified accounting','Heading2'),p('Independent verification recomputed 3,502 main checks and 1,564 nominal-baseline checks with zero discrepancies. It replayed observation masks, noise, all grid losses, selected hypotheses, saved trajectory scores and qualification flags. The 347 recorded v11/v12 files retain their hashes. Previous SoftVTBench and PhysTwin dataset results are unchanged; no new public-dataset gain is established by this simulation study.'),p('Contact repair is a separate experiment','Heading2'),p('The new development path integrates the material surface instead of relying on mesh vertices to sample a narrow support. Fixed midpoint sampling still fails the edge-drop world-trajectory gate even at 0.375 mm spacing. Exact integration of clipped plane/box contact footprints is being developed separately, with independent force/torque and friction-integration checks. No fresh test result is claimed here. Reference and predictor resolutions will be selected on development consistency, with the fixed acceptance bounds retained.'),p('Reproducibility and videos','Heading2'),p('Protocol and results: reports/coupled-contact-v13. Source and commands: scripts/coupled_contact_v13/README.txt. Audits: independent-audit.json, final-protocol-audit.txt, mesh-development-diagnostic.json and motion-population-audit.json. Raw trajectories and datasets remain local. Three video cases were declared before outcome inspection: test0-curved.mp4, test3-moving_sphere.mp4 and test7-edge_drop.mp4. They use common world coordinates, a moving camera, no deformation amplification and explicitly labeled 4x slower playback. The edge-drop clip retains a failed prediction.'),p('Interpretation','Heading2'),p('The useful progress is explicit two-way contact and improved prediction of a controlled simulator. Accurate physical identification, spatially trustworthy references, calibrated uncertainty, active probing superiority and stronger public-benchmark performance remain separate, unresolved questions.')])
    OUT.parent.mkdir(parents=True,exist_ok=True)
    SimpleDocTemplate(str(OUT),pagesize=A4,rightMargin=42,leftMargin=42,topMargin=42,bottomMargin=49,title='Position-based inference with coupled deformable contact',author='PhysGauss-SDE research campaign').build(story,onFirstPage=footer,onLaterPages=footer)
    dest=ROOT/'papers/coupled-contact-v13/report.pdf';dest.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(OUT,dest)
    (REPORT/'paper-build.json').write_text(json.dumps(dict(path=str(dest.relative_to(ROOT)),sha256=hashlib.sha256(dest.read_bytes()).hexdigest(),scope='Completed original v13; surface repair ongoing'),indent=2)+'\n')
    print(dest)

if __name__=='__main__':main()
